package com.codepilot1c.core.edt.metadata;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import com.google.gson.*;
import com._1c.g5.v8.dt.metadata.mdclass.*;
import com._1c.g5.v8.dt.moxel.*;
public class NativeContentModelsTest {
    private Catalog catalog(){var c=MdClassFactory.eINSTANCE.createCatalog();c.setName("Fixture");c.setCodeType(CatalogCodeType.STRING);c.setCodeLength(9);c.setDescriptionLength(40);return c;}
    private PredefinedWriter.ItemProps props(String json,boolean update){var parsed=JsonParser.parseString(json).getAsJsonObject();List<JsonObject> list=new ArrayList<>();parsed.entrySet().forEach(e->{var p=new JsonObject();p.addProperty("name",e.getKey());p.add("value",e.getValue());list.add(p);});var props=new PredefinedWriter.ItemProps();assertNull(PredefinedWriter.parseProperties(list,update,props));return props;}
    @Test public void createAndUpdatePreserveIdAndOmittedCode(){var c=catalog();var created=PredefinedWriter.create(c,"One",props("{\"code\":\"001\",\"description\":\"First\"}",false),true);assertFalse(created.error,created.isError());var id=created.item.getId();assertNotNull(id);var result=PredefinedWriter.modify(c,"One",props("{\"description\":\"Second\"}",true));assertFalse(result.error,result.isError());assertEquals(id,result.item.getId());assertEquals("001",NativeContentModels.predefined(c).get(0).get("code"));assertEquals("Second",result.item.getDescription());}
    @Test public void duplicateAndInvalidLengthDoNotMutateExistingItems(){var c=catalog();assertFalse(PredefinedWriter.create(c,"One",new PredefinedWriter.ItemProps(),true).isError());String before=NativeContentModels.fingerprint(c);assertTrue(PredefinedWriter.create(c,"one",new PredefinedWriter.ItemProps(),true).isError());assertTrue(PredefinedWriter.modify(c,"One",props("{\"code\":\"1234567890\"}",true)).isError());assertEquals(before,NativeContentModels.fingerprint(c));}
    @Test public void nativeCopyHasSameFingerprintAndPreviewDoesNotChangeOwner(){var c=catalog();String before=NativeContentModels.fingerprint(c);var copy=org.eclipse.emf.ecore.util.EcoreUtil.copy(c);assertEquals(before,NativeContentModels.fingerprint(copy));assertFalse(PredefinedWriter.create(copy,"Preview",new PredefinedWriter.ItemProps(),true).isError());assertEquals(before,NativeContentModels.fingerprint(c));assertNotEquals(before,NativeContentModels.fingerprint(copy));}
    @Test public void sparseReadReturnsOneBasedCellsAndNamedArea(){var sheet=MoxelFactory.eINSTANCE.createSpreadsheetDocument();var result=SpreadsheetTemplateWriter.apply(sheet,NativeContentModels.sheetPatch(new Gson().fromJson("{\"cells\":[{\"row\":2,\"col\":3,\"text\":\"Hello\"}],\"areas\":[{\"name\":\"Header\",\"fromRow\":2,\"fromCol\":3,\"toRow\":2,\"toCol\":4}]}",Map.class)));assertFalse(result.error,result.hasError());var read=NativeContentModels.sheet(sheet,1,5,1,5,10);var cells=(List<?>)read.get("cells");assertEquals(1,cells.size());assertEquals(2,((Map<?,?>)cells.get(0)).get("row"));assertEquals(3,((Map<?,?>)cells.get(0)).get("col"));assertFalse(((List<?>)read.get("named_areas")).isEmpty());}
    @Test public void spreadsheetPreviewDoesNotShareNonContainedColumns(){var doc=MoxelFactory.eINSTANCE.createSpreadsheetDocument();assertFalse(SpreadsheetTemplateWriter.apply(doc,JsonParser.parseString("{\"columnWidths\":[{\"col\":0,\"width\":40}]}").getAsJsonObject()).hasError());String before=NativeContentModels.fingerprint(doc);var copy=NativeContentModels.detachedCopy(doc);assertEquals(before,NativeContentModels.fingerprint(copy));assertFalse(SpreadsheetTemplateWriter.apply(copy,JsonParser.parseString("{\"columnWidths\":[{\"col\":0,\"width\":80}]}").getAsJsonObject()).hasError());assertEquals(before,NativeContentModels.fingerprint(doc));assertNotEquals(before,NativeContentModels.fingerprint(copy));}
    @Test public void sheetPatchRejectsFractionalAndZeroIndices(){for(var value:List.of(0,1.5)){try{NativeContentModels.sheetPatch(Map.of("cells",List.of(Map.of("row",value,"col",1,"text","test"))));fail();}catch(IllegalArgumentException expected){}}}
}
